def apply_attributes(source,target,mapping):
 count=0
 for a,b in zip(source.iter(),target.iter()):
  for attr in ('aria-label','summary','title'):
   v=a.get(attr)
   if v is not None and re.search('[A-Za-z]',v):
    assert a.get('id') in mapping,(a.get('id'),attr,v)
    new=mapping[a.get('id')]
    assert NUMBERS(v)==NUMBERS(new),(a.get('id'),NUMBERS(v),NUMBERS(new))
    b.set(attr,new);count+=1
 return count

def validate_pair(source,target):
 # Old integrity validator forbids changes to aria-label/summary. Check those
 # explicitly, then normalize only those allowed attributes in a validation copy.
 check=deepcopy(target)
 for a,b,c in zip(source.iter(),target.iter(),check.iter()):
  for attr in LANGUAGE_ATTRS:
   if attr in a.attrib:assert NUMBERS(a.get(attr))==NUMBERS(b.get(attr)),(a.get('id'),attr)
  for attr in ('aria-label','summary'):
   if attr in a.attrib:
    assert attr in b.attrib
    c.set(attr,a.get(attr))
 return _validate_pair(source,check)

def residual_attributes(root):
 return [{'id':e.get('id'),'attribute':k,'text':v} for e in root.iter() for k,v in e.attrib.items() if k in LANGUAGE_ATTRS and re.search('[A-Za-z]',v)]
